import sys
from collections import defaultdict

def main():
    import sys
    input = sys.stdin.read().split()
    n = int(input[0])
    edges = [(int(input[i*2+1])-1, input[i*2+2]) for i in range(n-1)]

    children = defaultdict(list)
    for i in range(1, n):
        p, c = edges[i-1]
        children[p].append((i, c))

    def dfs(node):
        odd_counts = [0] * 26
        max_path = 0
        for child, char in children[node]:
            child_odd_counts, child_max_path = dfs(child)
            max_path = max(max_path, child_max_path)
            for i in range(26):
                odd_counts[i] += child_odd_counts[i]

        current_max_path = 0
        odd_used = False
        for count in odd_counts:
            if count % 2 == 1:
                if not odd_used:
                    odd_used = True
                else:
                    current_max_path -= 1
            current_max_path += count // 2

        return odd_counts, max(current_max_path * 2 + odd_used, max_path)

    results = [0] * n
    for i in range(n):
        odd_counts, path_length = dfs(i)
        results[i] = path_length

    print(" ".join(map(str, results)))

if __name__ == "__main__":
    main()
